import{CARD_IMAGES}from'./card-images.js?v=0.156.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={'火':'#cf5144','水':'#358cbd','自然':'#449477','光':'#c0a34b','闇':'#7f649b'};
const validImage=url=>/^https:\/\/dm\.takaratomy\.co\.jp\/wp-content\/card\/(?:cardimage|cardthumb)\/[A-Za-z0-9_.-]+\.(?:jpg|png|webp)$/.test(url);
export function createCardArt({images=CARD_IMAGES}={}){
 const failed=new Set(),bound=new WeakSet();
 function sources(c){if(!c||c.hidden||c.faceDown||typeof c.id!=='string'||!/^\w[\w-]{1,70}$/.test(c.id)||c.id.startsWith('face-down-'))return [];const base='https://dm.takaratomy.co.jp/wp-content/card/',extra=validImage(images[c.id])?[]:[...(c.faces?.length>1?[base+'cardthumb/'+c.id+'a.jpg',base+'cardimage/'+c.id+'a.jpg']:[]),base+'cardimage/'+c.id+'.jpg'];return [...new Set([images[c.id],base+'cardthumb/'+c.id+'.jpg',...extra].filter(url=>validImage(url)&&!failed.has(url)))];}
 function html(c){if(!c||typeof c.id!=='string'||c.hidden||c.faceDown||c.id.startsWith('face-down-'))return '';const urls=sources(c),name=esc(c.name),civ=c.civilizations?.[0]||c.faces?.[0]?.civilizations?.[0]||c.civ,kind=c.faces?.[0]?.typeText||({creature:'クリーチャー',spell:'呪文',seed:'タマシード',field:'フィールド',gear:'クロスギア',castle:'G城'}[c.type]||'カード'),cost=c.faces?.length?c.faces.map(f=>f.costText||String(f.cost??'—')).join(' / '):c.cost??'—';return `<span class="art-card official-card ${urls.length?'is-loading':'image-unavailable'}" style="--civ-color:${colors[civ]||'#70868d'}" role="img" aria-label="${name}" data-card-art="${esc(c.id)}"><span class="official-card-fallback" aria-hidden="true"><span class="official-card-cost">${esc(cost)}</span><strong>${name}</strong><small class="official-card-kind">${esc(kind)}</small><small class="card-image-status">画像なし</small></span>${urls.length?`<img class="official-card-image" src="${esc(urls[0])}" data-card-image data-image-fallbacks="${esc(urls.slice(1).join('|'))}" alt="" draggable="false" loading="lazy" decoding="async" referrerpolicy="no-referrer" width="250" height="350">`:''}</span>`;}
 function bind(target){if(bound.has(target))return()=>{};bound.add(target);const image=e=>e.target?.matches?.('img[data-card-image]')?e.target:null;
  const load=e=>{const img=image(e);if(!img)return;const frame=img.closest('.official-card');frame?.classList.remove('is-loading','image-unavailable');frame?.classList.add('image-loaded');};
  const error=e=>{const img=image(e);if(!img)return;failed.add(img.currentSrc||img.src);const next=(img.dataset.imageFallbacks||'').split('|').filter(url=>validImage(url)&&!failed.has(url));if(next.length){img.dataset.imageFallbacks=next.slice(1).join('|');const frame=img.closest('.official-card');frame?.classList.remove('image-loaded');frame?.classList.add('is-loading');img.src=next[0];return;}img.hidden=true;const frame=img.closest('.official-card');frame?.classList.remove('is-loading','image-loaded');frame?.classList.add('image-unavailable');};
  target.addEventListener('load',load,true);target.addEventListener('error',error,true);return()=>{target.removeEventListener('load',load,true);target.removeEventListener('error',error,true);bound.delete(target);};
 }
 return{html,sources,bind};
}
